"use strict";

function addBackToTop(options = {}) {
  const {
    backgroundColor = "#000",
    cornerOffset = 20,
    diameter = 56,
    ease = progress => 0.5 * (1 - Math.cos(Math.PI * progress)),
    id = "back-to-top",
    innerHTML = `
      <svg viewBox="0 0 24 24">
        <path d="M7.41 15.41L12 10.83l4.59 4.58L18 14l-6-6-6 6z"></path>
      </svg>
    `,
    onClickScrollTo = 0,
    scrollContainer = document.body,
    scrollDuration = 100,
    showWhenScrollTopIs = 1,
    size = diameter,
    textColor = "#fff",
    zIndex = 1
  } = options;

  const isBodyScrollContainer = scrollContainer === document.body;
  const documentElement = isBodyScrollContainer
    ? document.documentElement
    : null;

  const iconSize = Math.round(0.43 * size);
  const iconMargin = Math.round(0.29 * size);

  // ---------------------------------------------------------------------------
  // Create button styles
  // ---------------------------------------------------------------------------

  const style = document.createElement("style");

  style.textContent = `
    #${id} {
      background: ${backgroundColor};
      border-radius: 50%;
      bottom: ${cornerOffset}px;
      box-shadow: 0 2px 5px 0 rgba(0, 0, 0, 0.26);
      color: ${textColor};
      cursor: pointer;
      display: block;
      height: ${size}px;
      opacity: 1;
      outline: 0;
      position: fixed;
      right: ${cornerOffset}px;
      -webkit-tap-highlight-color: transparent;
      -webkit-touch-callout: none;
      transition: bottom 0.2s, opacity 0.2s;
      user-select: none;
      width: ${size}px;
      z-index: ${zIndex};
    }

    #${id} svg {
      display: block;
      fill: currentColor;
      height: ${iconSize}px;
      margin: ${iconMargin}px auto 0;
      width: ${iconSize}px;
    }

    #${id}.hidden {
      bottom: -${size}px;
      opacity: 0;
    }
  `;

  document.head.insertAdjacentElement("afterbegin", style);

  // ---------------------------------------------------------------------------
  // Create button
  // ---------------------------------------------------------------------------

  const button = document.createElement("div");

  button.id = id;
  button.className = "hidden";
  button.innerHTML = innerHTML;

  button.addEventListener("click", event => {
    event.preventDefault();

    const targetPosition =
      typeof onClickScrollTo === "function"
        ? onClickScrollTo()
        : onClickScrollTo;

    smoothScrollTo(targetPosition);
  });

  document.body.appendChild(button);

  // ---------------------------------------------------------------------------
  // Scroll handling
  // ---------------------------------------------------------------------------

  let buttonIsHidden = true;

  function getScrollTop() {
    return (
      scrollContainer.scrollTop ||
      (documentElement && documentElement.scrollTop) ||
      0
    );
  }

  function setScrollTop(scrollTop) {
    scrollContainer.scrollTop = scrollTop;

    if (documentElement) {
      documentElement.scrollTop = scrollTop;
    }
  }

  function updateButtonVisibility() {
    const shouldShow = getScrollTop() >= showWhenScrollTopIs;

    if (shouldShow && buttonIsHidden) {
      button.className = "";
      buttonIsHidden = false;
    } else if (!shouldShow && !buttonIsHidden) {
      button.className = "hidden";
      buttonIsHidden = true;
    }
  }

  // ---------------------------------------------------------------------------
  // Smooth scrolling
  // ---------------------------------------------------------------------------

  function smoothScrollTo(targetPosition) {
    if (
      scrollDuration <= 0 ||
      typeof window.performance === "undefined" ||
      typeof window.requestAnimationFrame !== "function"
    ) {
      setScrollTop(targetPosition);
      return;
    }

    const startTime = performance.now();
    const startPosition = getScrollTop();
    const distance = startPosition - targetPosition;

    function animate(currentTime) {
      const progress = Math.min(
        (currentTime - startTime) / scrollDuration,
        1
      );

      const currentPosition =
        startPosition - Math.round(ease(progress) * distance);

      setScrollTop(currentPosition);

      if (progress < 1) {
        requestAnimationFrame(animate);
      }
    }

    requestAnimationFrame(animate);
  }

  // ---------------------------------------------------------------------------
  // Initialize
  // ---------------------------------------------------------------------------

  const scrollTarget = isBodyScrollContainer
    ? window
    : scrollContainer;

  scrollTarget.addEventListener("scroll", updateButtonVisibility);

  updateButtonVisibility();
}